// Fun Gradient Pallet Generator
vec3 pal(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b*cos(6.28318*(c*t+d));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //NORMALIZE UV from -1 to 1 
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;


    // Get time as T.
    float t = iTime * 1.0;

    // Final Color
    vec3 finCol = vec3(0.,0.,0.);


    // -------------------------//
    //      Editable Const.     //
    // -------------------------//

    // Makes the eye blink.
    // uv.x *= .999;


    //Cool Effect
    // uv.x *= cos(uv.x)*sin(uv.x)*2.1;


    // -------------------------//
    //         DO CODE          //
    // -------------------------//

    //Get the distance of UV from the center
    float d = length(uv);

    // Modulate Final Color based on distance and time.
    finCol = pal(d + t);

    d = sin(d*8.0 + t)/8.0;
    //d = abs(d);

    // Exponential decay to make it fit between 0 and 1
    d = 0.02 / d;

    finCol *= d;

    fragColor = vec4(finCol, 1.0);
}
